const Rtop = 5100;
const Rbottom = 10000;
const k = (Rtop + Rbottom) / Rbottom; // ≈ 1.51

const v_adc1 = msg.payload["/dev/i2c-1"].ads1115["0x48"].singleEnded.channel_0.Volts; 
msg.payload.ai1  = (v_adc1 * k).toFixed(2); // v

const v_adc2 = msg.payload["/dev/i2c-1"].ads1115["0x48"].singleEnded.channel_1.Volts;
msg.payload.ai2 = (v_adc2 * k).toFixed(2);


const Rshunt = 150;          

const v_adc3 = msg.payload["/dev/i2c-1"].ads1115["0x48"].singleEnded.channel_2.Volts; 
const i3 = v_adc3 / Rshunt;       
msg.payload.ai3 = (i3 * 1000).toFixed(2);          // mA

const v_adc4 = msg.payload["/dev/i2c-1"].ads1115["0x48"].singleEnded.channel_3.Volts; 
const i4 = v_adc4 / Rshunt;       
msg.payload.ai4 = (i4 * 1000).toFixed(2);          // mA

return msg;

